package deliveries
import("context";"time";"go.mongodb.org/mongo-driver/v2/bson")
type DispatchService struct{repo *Repository;offers *OfferRepository;plans *PlanRepository;riders RiderEligibility;nearby NearbyFinder;offerTTL time.Duration}
func NewDispatchService(r *Repository,o *OfferRepository,p *PlanRepository,re RiderEligibility,n NearbyFinder)*DispatchService{return &DispatchService{repo:r,offers:o,plans:p,riders:re,nearby:n,offerTTL:45*time.Second}}
func(s *DispatchService)Offer(ctx context.Context,deliveryID,riderID string)(AssignmentOffer,error){did,e:=bson.ObjectIDFromHex(deliveryID);if e!=nil{return AssignmentOffer{},ErrNotFound};rid,e:=bson.ObjectIDFromHex(riderID);if e!=nil{return AssignmentOffer{},ErrOffer};d,e:=s.repo.Find(ctx,did);if e!=nil{return AssignmentOffer{},e};if d.Status!=StatusRequested{return AssignmentOffer{},ErrState};ok,e:=s.riders.CanPublishLocation(ctx,rid.Hex());if e!=nil{return AssignmentOffer{},e};if !ok{return AssignmentOffer{},ErrForbidden};now:=time.Now().UTC();o:=AssignmentOffer{ID:bson.NewObjectID(),DeliveryID:did,RiderID:rid,Status:StatusOffered,CreatedAt:now,ExpiresAt:now.Add(s.offerTTL)};e=s.offers.Create(ctx,o);return o,e}
func(s *DispatchService)Accept(ctx,offerID,riderID string)(Public,error){oid,e:=bson.ObjectIDFromHex(offerID);if e!=nil{return Public{},ErrOffer};rid,e:=bson.ObjectIDFromHex(riderID);if e!=nil{return Public{},ErrForbidden};o,e:=s.offers.Find(ctx,oid);if e!=nil{return Public{},e};now:=time.Now().UTC();if now.After(o.ExpiresAt){return Public{},ErrOfferExpired};if o.RiderID!=rid||o.Status!=StatusOffered{return Public{},ErrOffer};ok,e:=s.offers.Respond(ctx,oid,rid,StatusOffered,StatusAssigned,now);if e!=nil{return Public{},e};if !ok{return Public{},ErrOffer};d,e:=s.repo.Find(ctx,o.DeliveryID);if e!=nil{return Public{},e};ok,e=s.repo.Transition(ctx,o.DeliveryID,StatusRequested,StatusAssigned,bson.M{"riderId":rid,"updatedAt":now},Event{DeliveryID:o.DeliveryID,Type:"rider_assignment_accepted",ActorID:rid,At:now});if e!=nil{return Public{},e};if !ok{return Public{},ErrState};d.Status=StatusAssigned;d.RiderID=&rid;d.UpdatedAt=now;return public(d),nil}
func(s *DispatchService)Decline(ctx,offerID,riderID string)error{oid,e:=bson.ObjectIDFromHex(offerID);if e!=nil{return ErrOffer};rid,e:=bson.ObjectIDFromHex(riderID);if e!=nil{return ErrForbidden};o,e:=s.offers.Find(ctx,oid);if e!=nil{return e};now:=time.Now().UTC();ok,e:=s.offers.Respond(ctx,oid,rid,StatusOffered,StatusDeclined,now);if e!=nil{return e};if !ok{return ErrOffer};plan,e:=s.plans.FindByDelivery(ctx,o.DeliveryID);if e!=nil{return e};if _,e:=s.plans.ClearActiveOffer(ctx,plan.ID,oid,now);e!=nil{return e};_,e=s.advance(ctx,&plan);if e==ErrNoNearbyRiders{return nil};return e}
func(s *DispatchService)ExpireAndAdvance(ctx context.Context,offerID string)error{oid,e:=bson.ObjectIDFromHex(offerID);if e!=nil{return ErrOffer};o,e:=s.offers.Find(ctx,oid);if e!=nil{return e};now:=time.Now().UTC();if now.Before(o.ExpiresAt){return ErrOffer};ok,e:=s.offers.Respond(ctx,oid,o.RiderID,StatusOffered,StatusExpired,now);if e!=nil{return e};if !ok{return nil};plan,e:=s.plans.FindByDelivery(ctx,o.DeliveryID);if e!=nil{return e};if _,e:=s.plans.ClearActiveOffer(ctx,plan.ID,oid,now);e!=nil{return e};_,e=s.advance(ctx,&plan);if e==ErrNoNearbyRiders{return nil};return e}
